import type { Metadata } from "next";
import { catalog } from "@/i18n/messages";
import { localePath, routing, type Locale } from "@/i18n/routing";
import { getProject } from "./content";
import { site } from "./site";

export const ogLocale: Record<Locale, string> = { en: "en_US", ar: "ar_AE" };

/** English is generated by app/og-image.png/route.tsx; Arabic is a committed PNG (npm run og:ar). */
const homeImage: Record<Locale, string> = { en: "/og-image.png", ar: "/images/og/ar/home.png" };

/** Canonical plus hreflang for one page. Relative: metadataBase makes them absolute on the canonical host. */
export function localeAlternates(locale: Locale, path: string): Metadata["alternates"] {
  return {
    canonical: localePath(locale, path),
    languages: {
      en: localePath("en", path),
      "ar-AE": localePath("ar", path),
      "x-default": localePath(routing.defaultLocale, path),
    },
  };
}

const otherLocale = (locale: Locale): Locale => (locale === "ar" ? "en" : "ar");

/** Site-wide metadata for a root layout; the values also serve as the locale's home page. */
export function rootMetadata(locale: Locale): Metadata {
  const { meta, common } = catalog(locale);
  const images = [{ url: homeImage[locale], width: 1200, height: 630, type: "image/png", alt: meta.ogImageAlt }];
  return {
    metadataBase: new URL(site.url),
    title: {
      default: meta.title,
      template: `%s | ${common.name}`,
    },
    description: meta.description,
    applicationName: common.name,
    authors: [{ name: site.name, url: site.url }],
    creator: site.name,
    alternates: localeAlternates(locale, "/"),
    openGraph: {
      type: "website",
      locale: ogLocale[locale],
      alternateLocale: ogLocale[otherLocale(locale)],
      url: localePath(locale, "/"),
      siteName: common.name,
      title: meta.title,
      description: meta.description,
      images,
    },
    twitter: {
      card: "summary_large_image",
      title: meta.title,
      description: meta.description,
      images,
    },
    robots: { index: true, follow: true },
    formatDetection: { telephone: false },
  };
}

/** Case-study metadata. The caller supplies the OG card, which differs by locale. */
export function projectMetadata(slug: string, locale: Locale, ogImage: { url: string; width: number; height: number }): Metadata {
  const project = getProject(slug, locale);
  if (!project) return {};
  const { caseStudy, common } = catalog(locale);
  const title = project.seoTitle;
  const description = project.seoDescription;
  const image = {
    ...ogImage,
    type: "image/png",
    alt: caseStudy.ogImageAlt
      .replace("{title}", `${project.title} ${project.titleAccent}`)
      .replace("{name}", common.name)
      .replace("{subtitle}", project.subtitle),
  };
  // openGraph replaces the root layout's object rather than merging it, so site-wide fields are repeated here.
  return {
    title,
    description,
    alternates: localeAlternates(locale, `/projects/${project.slug}`),
    openGraph: {
      type: "article",
      url: localePath(locale, `/projects/${project.slug}`),
      title,
      description,
      siteName: common.name,
      locale: ogLocale[locale],
      alternateLocale: ogLocale[otherLocale(locale)],
      authors: [site.url],
      images: [image],
    },
    twitter: { card: "summary_large_image", title, description, images: [image] },
  };
}
